SELECT 'konto_flaga' AS Regula,COUNT(*) AS Niepoprawne FROM Uzytkownicy WHERE NOT (Aktywny IN (0,1));
SELECT 'konto_imie' AS Regula,COUNT(*) AS Niepoprawne FROM Uzytkownicy WHERE NOT (CHAR_LENGTH(TRIM(Imie))>0);
SELECT 'konto_nazwisko' AS Regula,COUNT(*) AS Niepoprawne FROM Uzytkownicy WHERE NOT (CHAR_LENGTH(TRIM(Nazwisko))>0);
SELECT 'konto_email' AS Regula,COUNT(*) AS Niepoprawne FROM Uzytkownicy WHERE NOT (CHAR_LENGTH(TRIM(Email))>0);
SELECT 'konto_rola' AS Regula,COUNT(*) AS Niepoprawne FROM Uzytkownicy WHERE NOT (Rola IN ('klient','pracownik','admin'));
SELECT 'pracownik_flaga' AS Regula,COUNT(*) AS Niepoprawne FROM Pracownicy WHERE NOT (Aktywny IN (0,1));
SELECT 'placa' AS Regula,COUNT(*) AS Niepoprawne FROM Stanowiska WHERE NOT (Placa_brutto>=0);
SELECT 'stanowisko_nazwa' AS Regula,COUNT(*) AS Niepoprawne FROM Stanowiska WHERE NOT (CHAR_LENGTH(TRIM(Nazwa_stanowiska))>0);
SELECT 'typ_nazwa' AS Regula,COUNT(*) AS Niepoprawne FROM TypyPokoi WHERE NOT (CHAR_LENGTH(TRIM(NazwaTypu))>0);
SELECT 'pokoj_numer' AS Regula,COUNT(*) AS Niepoprawne FROM Pokoje WHERE NOT (NrPokoju>0);
SELECT 'pokoj_flaga' AS Regula,COUNT(*) AS Niepoprawne FROM Pokoje WHERE NOT (Aktywny IN (0,1));
SELECT 'pokoj_wersja' AS Regula,COUNT(*) AS Niepoprawne FROM Pokoje WHERE NOT (Wersja>=1);
SELECT 'pokoj_status' AS Regula,COUNT(*) AS Niepoprawne FROM Pokoje WHERE NOT (Status IN ('Wolny','Zajęty','Serwis'));
SELECT 'pobyt_wersja' AS Regula,COUNT(*) AS Niepoprawne FROM Rezerwacje WHERE NOT (Wersja>=1);
SELECT 'pobyt_status' AS Regula,COUNT(*) AS Niepoprawne FROM Rezerwacje WHERE NOT (Status IN ('Oczekująca','Potwierdzona','Ukończone','Anulowana'));
SELECT 'wizyta_wersja' AS Regula,COUNT(*) AS Niepoprawne FROM WizytyUslug WHERE NOT (Wersja>=1);
SELECT 'wizyta_status' AS Regula,COUNT(*) AS Niepoprawne FROM WizytyUslug WHERE NOT (Status IN ('Oczekująca','Potwierdzona','Ukończone','Anulowana'));
SELECT 'usluga_flaga' AS Regula,COUNT(*) AS Niepoprawne FROM Uslugi_dodatkowe WHERE NOT (Czydostepna IN (0,1));
SELECT 'usluga_nazwa' AS Regula,COUNT(*) AS Niepoprawne FROM Uslugi_dodatkowe WHERE NOT (CHAR_LENGTH(TRIM(Nazwa_Uslugi))>0);
SELECT 'kategoria_nazwa' AS Regula,COUNT(*) AS Niepoprawne FROM KategorieUslug WHERE NOT (CHAR_LENGTH(TRIM(Nazwa))>0);
SELECT 'blokada_powod' AS Regula,COUNT(*) AS Niepoprawne FROM BlokadyPokoi WHERE NOT (CHAR_LENGTH(TRIM(Powod))>0);
SELECT 'grafik_typ' AS Regula,COUNT(*) AS Niepoprawne FROM GrafikPracownikow WHERE NOT (TypDnia IN ('Praca','Urlop','Zwolnienie','Wolne'));
SELECT 'grafik_doba' AS Regula,COUNT(*) AS Niepoprawne FROM GrafikPracownikow WHERE NOT (TypDnia<>'Praca' OR (GodzinaOd>='00:00:00' AND GodzinaDo<'24:00:00'));
SELECT 'pobyt_osoby_pojemnosc' AS Regula,COUNT(*) AS Niepoprawne FROM Rezerwacje r JOIN Pokoje p ON p.ID_Pokoju=r.ID_Pokoju WHERE r.Status IN ('Oczekująca','Potwierdzona') AND r.LiczbaOsob>p.IloscOsob;
SELECT 'nakladajace_pobyty' AS Regula,COUNT(*) AS Niepoprawne FROM Rezerwacje a JOIN Rezerwacje b ON a.ID_Rezerwacji<b.ID_Rezerwacji AND a.ID_Pokoju=b.ID_Pokoju AND a.DataOd<b.DataDo AND a.DataDo>b.DataOd WHERE a.Status IN ('Oczekująca','Potwierdzona') AND b.Status IN ('Oczekująca','Potwierdzona');
SELECT 'pobyt_blokada' AS Regula,COUNT(*) AS Niepoprawne FROM Rezerwacje r JOIN BlokadyPokoi b ON b.ID_Pokoju=r.ID_Pokoju AND r.DataOd<b.DataDo AND r.DataDo>b.DataOd WHERE r.Status IN ('Oczekująca','Potwierdzona');
SELECT 'nakladajace_wizyty' AS Regula,COUNT(*) AS Niepoprawne FROM WizytyUslug a JOIN WizytyUslug b ON a.ID_Wizyty<b.ID_Wizyty AND a.ID_Pracownika=b.ID_Pracownika AND a.DataOd<b.DataDo AND a.DataDo>b.DataOd WHERE a.Status IN ('Oczekująca','Potwierdzona') AND b.Status IN ('Oczekująca','Potwierdzona');